contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address logger) public {
        require(logger != address(this));
        bool initiallyApproved = c.approvedToLog(logger); if (__ESBMC_reverted()) return;
        bool r1 = c.logFunded(); if (__ESBMC_reverted()) return;
        bool r2 = c.logRedeemed(bytes32(uint256(1))); if (__ESBMC_reverted()) return;
        assert(!initiallyApproved && !r1 && !r2);
    }
    receive() external payable {}
}

